export const overrideTokens = (base, overrides) => {
    return Object.keys(base).reduce((acc, key) => {
        const overrideValue = overrides[key];
        const resolvedValue = overrideValue || overrideValue === 0 ? overrideValue : base[key];
        return Object.assign(Object.assign({}, acc), { [key]: resolvedValue });
    }, {});
};
