'use client';
import React from 'react';
import { createUseStyles as CssInJsCreateUseStyles, createTheming, } from 'react-jss';
import { createTheme } from './createTheme';
import { getThemeDefaults } from './utils';
//#region Перезапись дефолтной темы с помощью глобальной переменной DEFAULT_UIK_THEME (только для команды ИДС, в остальных случаях не рекомендуется к использованию!!!)
const defaultTheme = createTheme(getThemeDefaults());
//#endregion
const ThemeContext = React.createContext(defaultTheme);
const theming = createTheming(ThemeContext);
const { withTheme, ThemeProvider: ReactJssThemeProvider, useTheme } = theming;
/**
 *
 */
function createUseStyles(styles, options) {
    return CssInJsCreateUseStyles(styles, Object.assign({ theming }, options));
}
export { withTheme, ReactJssThemeProvider, useTheme, createUseStyles };
