import * as React from 'react';
import * as ReactDOM from 'react-dom';
export const Portal = ({ children, container, }) => {
    const [mountNode, setMountNode] = React.useState();
    React.useEffect(() => {
        setMountNode(typeof container === 'function' ? container() : container || document.body);
    }, [container]);
    return mountNode ? ReactDOM.createPortal(children, mountNode) : null;
};
