const trimString = (str) => str.replace(/^\s+|\s+$/g, '');
const defaultStringify = (option) => `${option.label} ${option.value}`;
export const createFilter = (config) => (option, rawInput) => {
    // чтобы возможность создавать опции всегда присутствовала, в не зависимости как мы конфигурируем поиск
    if (option.option.__isCreating__) {
        return true;
    }
    const { ignoreCase, stringify, trim, matchFrom } = Object.assign({ ignoreCase: true, stringify: defaultStringify, trim: true, matchFrom: 'any' }, config);
    let input = trim ? trimString(rawInput) : rawInput;
    let candidate = trim ? trimString(stringify(option)) : stringify(option);
    if (ignoreCase) {
        input = input.toLowerCase();
        candidate = candidate.toLowerCase();
    }
    return matchFrom === 'start'
        ? candidate.substr(0, input.length) === input
        : candidate.indexOf(input) > -1;
};
