import * as React from 'react';
import { enableBodyScroll, disableBodyScroll, } from '@v-uik/utils';
/**
 * Блокирует прокрутку тела страницы при монтировании элемента.
 *
 * @param options
 */
export const useBodyScrollLock = (options) => {
    const innerRef = React.useRef(null);
    const lockOnMountNodeRef = React.useCallback((node) => {
        if (node) {
            disableBodyScroll(node, Object.assign({ reserveScrollBarGap: true }, options));
        }
        else {
            enableBodyScroll(innerRef.current);
        }
        innerRef.current = node;
    }, [options]);
    const unlockOnUnmountNodeRef = React.useCallback((node) => {
        if (!node) {
            enableBodyScroll(innerRef.current);
        }
        innerRef.current = node;
    }, []);
    return {
        enableBodyScroll,
        disableBodyScroll,
        lockOnMountNodeRef,
        unlockOnUnmountNodeRef,
    };
};
