'use client';
import * as React from 'react';
const maxRules = 1e10;
const createGenerateId = () => {
    let id = 0;
    return () => {
        id++;
        if (id > maxRules) {
            console.warn('[@v-uik/hooks] Сгенерированный id превышает лимит');
        }
        return id;
    };
};
const GeneratedIdContext = React.createContext(createGenerateId());
export const GeneratedIdProvider = ({ children, }) => {
    const generateId = React.useMemo(() => createGenerateId(), []);
    return (React.createElement(GeneratedIdContext.Provider, { value: generateId }, children));
};
export const useGeneratedId = (overrideId) => {
    const idRef = React.useRef(overrideId);
    const generateId = React.useContext(GeneratedIdContext);
    if (idRef.current == null) {
        idRef.current = `v-uik-${generateId()}`;
    }
    return idRef.current;
};
