export const splitArrayIntoChunks = (array, chunkSize = 0) => {
    const result = [];
    if (chunkSize > 0) {
        while (array.length) {
            result.push(array.splice(0, chunkSize));
        }
    }
    return result;
};
export const noop = () => { }; // eslint-disable-line @typescript-eslint/no-empty-function
