import { useDataDateAttribute, } from '../useDataDateAttribute';
import { useDateLibAdapter } from '../useDateLibAdapter';
import * as React from 'react';
import { DataGridNavigationDirection } from '@v-uik/hooks';
import { useDatePickerNavigation, } from '../useDatePickerNavigation';
import { getButtonCountInRow } from '../../utils/getButtonCountInRow';
/**
 * Хук для навигации QuarterView.
 *
 * @param root0
 * @param root0.displayedDate
 */
export function useQuarterViewNavigation({ displayedDate, }) {
    const adapter = useDateLibAdapter();
    // контейнер, в котором лежат кнопки (grid)
    const [containerNode, setContainerNode] = React.useState(null);
    // Навигация: шаг = 3 месяца
    const handleQuarterNavigation = React.useCallback((dir, date) => {
        const STEP = 3;
        // влево/вправо шагаем на 1 квартал
        let newDate = adapter.addMonths(date, dir === DataGridNavigationDirection.right ? STEP : -STEP);
        // вверх/вниз — на целую строку кварталов
        const verticalDirections = [
            DataGridNavigationDirection.top,
            DataGridNavigationDirection.bottom,
        ];
        if (verticalDirections.includes(dir)) {
            // считываем, сколько в строке кварталов
            // (на широких экранах обычно 4 в ряд, но пусть динамически)
            const countInRow = getButtonCountInRow(containerNode, document.activeElement);
            const delta = dir === DataGridNavigationDirection.bottom
                ? countInRow * STEP
                : -countInRow * STEP;
            newDate = adapter.addMonths(date, delta);
        }
        return newDate;
    }, [adapter, containerNode]);
    // Проверяем: две даты в одном квартале?
    const isSameDatePeriod = React.useCallback((d1, d2) => {
        const y1 = adapter.getYear(d1);
        const y2 = adapter.getYear(d2);
        const q1 = Math.floor(adapter.getMonth(d1) / 3);
        const q2 = Math.floor(adapter.getMonth(d2) / 3);
        return y1 === y2 && q1 === q2;
    }, [adapter]);
    // Из useDataDateAttribute('quarter') получаем:
    // - generateDataDateAttribute: сериализация для data-date
    // - parseDataDateAttribute: парсер обратно в TDate
    const { generateDataDateAttribute, parseDataDateAttribute } = useDataDateAttribute('month');
    // Собираем готовую логику стрелочной навигации
    const { buttonOnFocus, onKeyDown } = useDatePickerNavigation({
        displayedDate,
        onNavigate: handleQuarterNavigation,
        generateDataDateAttribute,
        parseDataDateAttribute,
        isSameDatePeriod,
    });
    return {
        buttonOnFocus,
        onKeyDown,
        generateDataDateAttribute,
        setContainerNode,
    };
}
