import { useCallback } from 'react';
/**
 * Поиск элементов по data-date атрибуту.
 *
 * @param generateDataDateAttribute
 */
export const useFindElementByDate = (generateDataDateAttribute) => {
    return useCallback((date) => {
        if (!date) {
            return null;
        }
        return document.querySelector(`[data-date="${generateDataDateAttribute(date)}"]`);
    }, [generateDataDateAttribute]);
};
