/**
 * Утилита для объединения классов.
 *
 * @param classes1 Набор классов.
 * @param classes1.classes1 Набор классов.
 * @param classes1.classes2 Набор классов.
 * @param classes1.mergeCallback Функция для объединения классов.
 *
 * @returns Объект с объединенными классами.
 */
export const mergeClasses = ({ classes1, classes2, mergeCallback, }) => {
    if (!classes2) {
        return classes1;
    }
    const result = Object.assign({}, classes1);
    Object.keys(classes2).forEach((classKey) => {
        // @ts-ignore вернуться позже
        result[classKey] = mergeCallback(result[classKey], classes2[classKey]);
    });
    return result;
};
