// переработанный код из https://github.com/rick-liruixin/body-scroll-lock-upgrade
// оригинальная библиотека более не поддерживается
// удалены все специальные обработчики для iOS, т.к. они ломают скролл Modal/Drawer
// без них всё работает корректно. Проверено на iOS 15.5, 18.6
import { warning } from '../warning';
let locks = [];
let previousBodyOverflowSetting;
let previousBodyPaddingRight;
const setOverflowHidden = (options) => {
    // If previousBodyPaddingRight is already set, don't set it again.
    if (previousBodyPaddingRight === undefined) {
        const reserveScrollBarGap = !!options && options.reserveScrollBarGap === true;
        const scrollBarGap = window.innerWidth - document.documentElement.getBoundingClientRect().width;
        if (reserveScrollBarGap && scrollBarGap > 0) {
            const computedBodyPaddingRight = parseInt(window
                .getComputedStyle(document.body)
                .getPropertyValue('padding-right'), 10);
            previousBodyPaddingRight = document.body.style.paddingRight;
            document.body.style.paddingRight = `${computedBodyPaddingRight + scrollBarGap}px`;
        }
    }
    // If previousBodyOverflowSetting is already set, don't set it again.
    if (previousBodyOverflowSetting === undefined) {
        previousBodyOverflowSetting = document.body.style.overflow;
        document.body.style.overflow = 'hidden';
    }
};
const restoreOverflowSetting = () => {
    if (previousBodyPaddingRight !== undefined) {
        document.body.style.paddingRight = previousBodyPaddingRight;
        // Restore previousBodyPaddingRight to undefined so setOverflowHidden knows it
        // can be set again.
        previousBodyPaddingRight = undefined;
    }
    if (previousBodyOverflowSetting !== undefined) {
        document.body.style.overflow = previousBodyOverflowSetting;
        // Restore previousBodyOverflowSetting to undefined
        // so setOverflowHidden knows it can be set again.
        previousBodyOverflowSetting = undefined;
    }
};
/**
 *
 * @param lockId - идентификатор для случая, когда функция вызывается несколько раз. Используйте string. HTMLElement оставлен для обратной совместимости.
 * @param options - настройки блокировки скролла.
 * @returns void
 */
export const disableBodyScroll = (lockId, options) => {
    if (!lockId) {
        warning(false, 'Utils - bodyScrollLock', 'Необходимо передать lockId');
        return;
    }
    if (locks.some((lock) => lock === lockId)) {
        warning(false, 'Utils - bodyScrollLock', 'Такой lockId уже был передан');
        return;
    }
    locks.push(lockId);
    setOverflowHidden(options);
};
export const clearAllBodyScrollLocks = () => {
    restoreOverflowSetting();
    locks = [];
};
/**
 * @param lockId - идентификатор для случая, когда функция вызывается несколько раз. Используйте string. HTMLElement оставлен для обратной совместимости.
 * @returns void
 */
export const enableBodyScroll = (lockId) => {
    if (!lockId) {
        warning(false, 'Utils', 'Необходимо передать lockId');
        return;
    }
    locks = locks.filter((lock) => lock !== lockId);
    if (!locks.length) {
        restoreOverflowSetting();
    }
};
