import * as React from 'react';
import { detectOverflow } from '@popperjs/core';
import { usePreviousPropCompare } from '@v-uik/hooks';
import { defineListSizeParameters } from '../utils';
const defaultViewportPadding = 16;
export const useSelectModifiers = ({ modifiers, limitByWidth, indexOfSelected = 0, activeOption, openUnderAnchor, enableFlip = false, isOpened = true, rows, maxLength, }) => {
    const shouldCalculateScrollByOption = usePreviousPropCompare(activeOption, (x, prev) => x === prev);
    const shouldCalculateScrollByOpened = usePreviousPropCompare(isOpened, (x, prev) => x !== prev);
    // условие расчета для элементов, находящихся за видимым контейнером, в случае прибитых строк
    const rowsCondition = rows && rows < indexOfSelected + 2;
    return React.useMemo(() => [
        ...(modifiers !== null && modifiers !== void 0 ? modifiers : []),
        {
            name: 'flip',
            enabled: enableFlip,
        },
        {
            name: 'preventOverflow',
            enabled: false,
        },
        {
            name: 'calculatePosition',
            enabled: true,
            phase: 'main',
            requiresIfExists: ['offset', 'preventOverflow'],
            fn: ({ state, name, options, }) => {
                const overflow = detectOverflow(state, options);
                const popperHeight = state.rects.popper.height;
                const maxAvailableSize = window.innerHeight - 2 * defaultViewportPadding;
                const isViewportEnough = maxAvailableSize >= popperHeight;
                const popperOffsets = state.modifiersData.popperOffsets;
                if (isViewportEnough) {
                    const { optionHeight, listBorder, listPadding } = defineListSizeParameters(state);
                    if (!openUnderAnchor) {
                        const availableOffset = Math.abs(overflow.top) - defaultViewportPadding;
                        // расчет позиции по-умолчанию, для начальных видимых элементов контейнера, без возможности скролла вверх
                        let requiredShift = (indexOfSelected + 1) * optionHeight + listPadding + listBorder;
                        if (rowsCondition) {
                            if (!rows) {
                                throw new Error('Rows must be defined!');
                            }
                            // необходимое значение выбранного пункта, чтобы сверху/под ним распологалось одинаковое количество элементов
                            const halfRows = Math.round(rows / 2);
                            if (indexOfSelected + 1 + halfRows > maxLength) {
                                // расчет позиции для последних видимых элементов контейнера, без возможности скролла вниз
                                requiredShift =
                                    (rows - (maxLength - indexOfSelected - 1)) * optionHeight -
                                        listPadding -
                                        listBorder;
                            }
                            else {
                                // расчет позиции для центральных элементов списка, со скроллом вверх/вниз
                                requiredShift = halfRows * optionHeight;
                            }
                        }
                        if (availableOffset > requiredShift) {
                            const bottomOverflow = overflow.bottom - requiredShift + defaultViewportPadding;
                            popperOffsets.y =
                                defaultViewportPadding +
                                    (availableOffset - requiredShift) -
                                    (bottomOverflow > 0 ? bottomOverflow : 0);
                        }
                        else {
                            popperOffsets.y = defaultViewportPadding;
                        }
                    }
                }
                else {
                    state.modifiersData[name] = {
                        maxHeight: maxAvailableSize,
                    };
                    popperOffsets.y = defaultViewportPadding;
                }
            },
        },
        {
            name: 'minWidth',
            enabled: true,
            phase: 'beforeWrite',
            requires: ['computeStyles'],
            fn: ({ state }) => {
                state.styles.popper.minWidth = `${state.rects.reference.width}px`;
            },
            effect: ({ state }) => {
                state.elements.popper.style.minWidth = `${state.elements.reference.offsetWidth}px`;
            },
        },
        ...(limitByWidth
            ? [
                {
                    name: 'limitByWidth',
                    enabled: true,
                    phase: 'beforeWrite',
                    requires: ['computeStyles'],
                    fn: ({ state }) => {
                        state.styles.popper.width = `${state.rects.reference.width}px`;
                    },
                    effect: ({ state, }) => {
                        state.elements.popper.style.width = `${state.elements.reference.offsetWidth}px`;
                    },
                },
            ]
            : [
                {
                    name: 'maxWidth',
                    enabled: true,
                    phase: 'main',
                    requiresIfExists: ['offset', 'flip'],
                    fn: ({ state, name, options, }) => {
                        const overflow = detectOverflow(state, options);
                        const [basePlacement] = state.placement.split('-');
                        const widthProp = basePlacement === 'left' ? 'left' : 'right';
                        state.modifiersData[name] =
                            state.rects.popper.width -
                                overflow[widthProp] -
                                2 * defaultViewportPadding;
                    },
                },
                {
                    name: 'applyMaxWidth',
                    enabled: true,
                    phase: 'beforeWrite',
                    requires: ['maxWidth'],
                    fn: ({ state }) => {
                        state.styles.popper.maxWidth = `${state.modifiersData.maxWidth}px`;
                    },
                },
            ]),
        {
            name: 'listStyles',
            enabled: true,
            phase: 'beforeWrite',
            requires: ['computeStyles', 'calculatePosition'],
            fn: ({ state }) => {
                const { maxHeight } = state.modifiersData
                    .calculatePosition;
                if (maxHeight) {
                    ;
                    state.elements.popper.firstElementChild.style.maxHeight = `${maxHeight}px`;
                }
            },
        },
        {
            name: 'calculateScrollPosition',
            enabled: true,
            phase: 'afterWrite',
            fn: ({ state }) => {
                const { listElement, listPadding, listBorder, optionHeight, referenceBounds, } = defineListSizeParameters(state);
                const isScrollable = listElement.clientHeight !== listElement.scrollHeight;
                if (isScrollable &&
                    shouldCalculateScrollByOption &&
                    shouldCalculateScrollByOpened) {
                    let referenceTopOffset = referenceBounds.top;
                    if (rowsCondition) {
                        if (!rows) {
                            throw new Error('Rows must be defined!');
                        }
                        // необходимое значение выбранного пункта, чтобы сверху/под ним распологалось одинаковое количество элементов
                        const halfRows = Math.round(rows / 2);
                        // отсечка скролла до центрального элемента в списке
                        referenceTopOffset =
                            halfRows * optionHeight - listBorder - listPadding;
                    }
                    const selectedScrollToTopOffset = indexOfSelected * optionHeight;
                    // расчеты, если список находится слишком высоко/низко
                    let scrollCorrection = 0;
                    if (defaultViewportPadding > referenceTopOffset) {
                        scrollCorrection =
                            referenceTopOffset -
                                defaultViewportPadding -
                                listPadding -
                                listBorder;
                    }
                    else {
                        const referenceBottomOffset = window.innerHeight - referenceBounds.bottom;
                        if (defaultViewportPadding > referenceBottomOffset) {
                            scrollCorrection =
                                defaultViewportPadding -
                                    referenceBottomOffset +
                                    listPadding +
                                    listBorder;
                        }
                    }
                    const scrollOffset = selectedScrollToTopOffset - referenceTopOffset + scrollCorrection;
                    listElement.scrollTo(0, scrollOffset);
                }
            },
        },
    ], [
        modifiers,
        limitByWidth,
        indexOfSelected,
        openUnderAnchor,
        shouldCalculateScrollByOption,
        enableFlip,
        shouldCalculateScrollByOpened,
        rows,
        maxLength,
        rowsCondition,
    ]);
};
