import React from 'react';
import { validateRange } from '../utils/date';
import { useDateLibAdapter } from './useDateLibAdapter';
export const useRangeMaskedInputValidation = ({ disableDate, disableFuture, disablePast, maxDate, minDate, }) => {
    const [validationErrorStart, setValidationErrorStart] = React.useState(null);
    const [validationErrorEnd, setValidationErrorEnd] = React.useState(null);
    const adapter = useDateLibAdapter();
    const validate = ({ range, index, }) => {
        const [start, end] = validateRange(range, index, adapter, {
            disableDate,
            disableFuture,
            disablePast,
            maxDate,
            minDate,
        });
        setValidationErrorStart(start);
        setValidationErrorEnd(end);
        return !start && !end
            ? null
            : [start, end];
    };
    const resetErrors = () => {
        setValidationErrorStart(null);
        setValidationErrorEnd(null);
    };
    return {
        validate,
        validationErrorEnd,
        validationErrorStart,
        resetErrors,
    };
};
