import * as React from 'react';
/**
 *
 */
export function childrenToArray(children) {
    let ret = [];
    React.Children.forEach(children, (child) => {
        if (child === undefined || child === null) {
            return;
        }
        if (Array.isArray(child)) {
            ret = ret.concat(childrenToArray(child));
        }
        else if (React.isValidElement(child) && child.props) {
            // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
            ret = ret.concat(childrenToArray(child.props.children));
        }
        else {
            ret.push(child);
        }
    });
    return ret;
}
/**
 *
 */
export function getChildrenText(children) {
    return childrenToArray(children).join('');
}
