import { ESCAPE_CHAR, DEFAULT_PLACEHOLDER_CHAR, DEFAULT_FORMAT_CHARACTERS, } from './constants';
/**
 * Класс шаблона маски.
 */
export class Pattern {
    /**
     * @param source Маска.
     * @param formatCharacters Правила обработки символов маски.
     * @param placeholderChar Символ-заполнитель.
     * @param placeholderString Строка-заполнитель (имеет более высокий приоритет, чем символ).
     */
    constructor(source, formatCharacters = DEFAULT_FORMAT_CHARACTERS, placeholderChar = DEFAULT_PLACEHOLDER_CHAR, placeholderString) {
        this.editableIndices = {};
        if (!(this instanceof Pattern)) {
            return new Pattern(source, formatCharacters, placeholderChar, placeholderString);
        }
        if (placeholderString) {
            this.placeholderString = placeholderString.split('');
        }
        this.placeholderChar = placeholderChar;
        this.formatCharacters = formatCharacters;
        this.source = source;
        this.pattern = [];
        this.length = 0;
        this.firstEditableIndex = -1;
        this.lastEditableIndex = -1;
        this.editableIndices = {};
        this.parse();
    }
    /**
     * Разбор на редактируемые и не редактируемые символы по маске.
     */
    parse() {
        const sourceChars = this.source.split('');
        let patternIndex = 0;
        const pattern = [];
        for (let i = 0; i < sourceChars.length; i++) {
            let char = sourceChars[i];
            if (char === ESCAPE_CHAR) {
                if (i === sourceChars.length - 1) {
                    throw new Error(`MaskedInputCore: pattern ends with an escape character ${ESCAPE_CHAR}`);
                }
                char = sourceChars[++i];
            }
            else if (char in this.formatCharacters) {
                if (this.firstEditableIndex === -1) {
                    this.firstEditableIndex = patternIndex;
                }
                this.lastEditableIndex = patternIndex;
                this.editableIndices[patternIndex] = true;
            }
            pattern.push(char);
            patternIndex++;
        }
        if (this.firstEditableIndex === -1) {
            throw new Error(`MaskedInputCore: pattern "${this.source}" does not contain any editable characters.`);
        }
        this.pattern = pattern;
        this.length = pattern.length;
    }
    /**
     * Возвращает символ-заполнитель для ещё не введённых редактируемых индексов.
     */
    getPlaceholderChar(index) {
        return ((this.placeholderString && this.placeholderString[index]) ||
            this.placeholderChar);
    }
    /**
     * Форматирование значения по шаблону.
     *
     * @param value Исходное значение.
     *
     * @returns Отформатированное значения.
     */
    formatValue(value) {
        const valueBuffer = new Array(this.length);
        let valueIndex = 0;
        for (let i = 0; i < this.length; i++) {
            if (this.isEditableIndex(i)) {
                valueBuffer[i] =
                    value.length > valueIndex && this.isValidAtIndex(value[valueIndex], i)
                        ? this.transform(value[valueIndex], i)
                        : this.getPlaceholderChar(i);
                valueIndex++;
            }
            else {
                valueBuffer[i] = this.pattern[i];
                let skipMaskedStaticSymbols = false;
                if (value.length !== this.pattern.length) {
                    // Проверяем, что значение может совпадать с символом маски и его можно указать на конкретном индексе
                    for (let j = 0; j < this.pattern.length; j++) {
                        if (this.pattern[j] &&
                            this.isEditableIndex(j) &&
                            this.isValidAtIndex(value[valueIndex], j)) {
                            skipMaskedStaticSymbols = true;
                            break;
                        }
                    }
                    if (skipMaskedStaticSymbols) {
                        continue;
                    }
                }
                // Позволяем значениям содержать статические символы из шаблона.
                if (value.length > valueIndex &&
                    value[valueIndex] === this.pattern[i]) {
                    valueIndex++;
                }
            }
        }
        return valueBuffer;
    }
    /**
     * Является ли данный индекс редактируемым.
     *
     * @param index Индекс для проверки.
     *
     * @returns Результат проверки.
     */
    isEditableIndex(index) {
        return this.editableIndices[index];
    }
    /**
     * Подходит ли маске данный символ в данной позиции.
     *
     * @param char Символ для проверки.
     * @param index Позиция символа.
     *
     * @returns Результат проверки.
     */
    isValidAtIndex(char, index) {
        return this.formatCharacters[this.pattern[index]].validate(char);
    }
    /**
     * Трансформация символа по маске.
     *
     * @param char Символ для трансформации.
     * @param index Позиция символа.
     *
     * @returns Трансформированный символ.
     */
    transform(char, index) {
        const format = this.formatCharacters[this.pattern[index]];
        return typeof format.transform === 'function'
            ? format.transform(char)
            : char;
    }
    /**
     * Возвращает исходное значение по отформатированному и маске.
     *
     * @param value Массив символов поля.
     * @param value Индексы символов, на которых нужно указать пробелы.
     *
     * @returns String Значение поля в формате строки.
     */
    getRawValue(value, emptyCharsIndexes = []) {
        const rawValue = [];
        for (let i = 0; i < value.length; i++) {
            if (this.isEditableIndex(i)) {
                const valueIsPlaceholderChar = value[i] === this.getPlaceholderChar(i);
                if (emptyCharsIndexes.includes(i) && valueIsPlaceholderChar) {
                    // Указываем неразрывные пробелы, чтобы они не тримились и не затирались
                    rawValue.push('\u00A0');
                }
                else if (!valueIsPlaceholderChar) {
                    rawValue.push(value[i]);
                }
            }
        }
        return rawValue.join('');
    }
}
