const maxRules = 1e10;
// копипаста из hooks useGenerateId. Функцию здесь оставляю для обратной совместимости
const createGenerateId = () => {
    let id = 0;
    return () => {
        id++;
        if (id > maxRules) {
            console.warn('[@v-uik/utils] Сгенерированный id превышает лимит');
        }
        return `v-uik-${id}`;
    };
};
/**
 * Функция для генерации уникального идентификатора с префиксом @v-uik-.
 */
export const generateId = createGenerateId();
