/**
 * Функция возврщаюащая доп пропсы.
 *
 * @param props
 */
export const getExternalComponentsProps = (props) => {
    const defaultProps = {
        yearBarButtonProps: {},
        dayViewProps: {},
        monthBarButtonProps: {},
        monthViewProps: {},
        yearViewProps: {},
        quarterViewProps: {},
        nextNavigationBarButtonProps: {},
        prevNavigationBarButtonProps: {},
    };
    if (!props) {
        return defaultProps;
    }
    return Object.assign(Object.assign({}, defaultProps), props);
};
