export const getTreeItemChildren = (item) => item.children;
export const getTreeItemKey = (item) => item.key;
export const getTreeItemLabel = (item) => item.label;
export const getTreeItemDisabled = (item) => !!item.disabled;
export const getTreeItemCheckDisabled = (item) => !!item.checkDisabled;
export const getTreeItemSelectDisabled = (item) => !!item.selectDisabled;
export const getTreeItemLoadable = (item) => !!item.loadable;
