const initialItem = {
    value: '',
    hasCaret: false,
    neighborLeft: null,
    neighborRight: null,
};
/**
 *
 * @param items
 * @param caretPosition
 */
export const createList = (items, caretPosition) => {
    return items.reduce((data, value, index) => {
        const prevIndex = index - 1;
        const hasCaret = caretPosition === index;
        const previousItem = data[prevIndex];
        const item = Object.assign(Object.assign({}, initialItem), { hasCaret,
            value });
        if (previousItem) {
            item.neighborLeft = previousItem;
            previousItem.neighborRight = item;
        }
        return data.push(item), data;
    }, []);
};
