import * as React from 'react';
export const useHoverState = (range, activeInputIndex) => {
    const [hoverDate, setHoverDate] = React.useState(null);
    const shouldTrackHover = (activeInputIndex === 0 && range[1]) || (activeInputIndex === 1 && range[0]);
    return {
        hoverDate,
        setHoverDate: shouldTrackHover ? setHoverDate : undefined,
    };
};
