'use client';
import * as React from 'react';
const TreeFeatureFlagsContext = React.createContext({});
/**
 * Провайдер для изменения Feature-Flag'ов всего дерева
 */
export const TreeFeatureFlagsContextProvider = ({ children }) => {
    const skipFocusOnTreeRef = React.useRef(false);
    const skipExpandRef = React.useRef(false);
    const skipFocusEffectRef = React.useRef(false);
    const skipSelectRef = React.useRef(false);
    const value = React.useMemo(() => ({
        skipFocusOnTreeRef,
        skipExpandRef,
        skipFocusEffectRef,
        skipSelectRef,
    }), []);
    return (React.createElement(TreeFeatureFlagsContext.Provider, { value: value }, children));
};
/**
 * Хук для изменения Feature-Flag'ов всего дерева
 */
export const useTreeFeatureFlagsContext = () => {
    const context = React.useContext(TreeFeatureFlagsContext);
    if (!context) {
        throw new Error('Hook useTreeFeatureFlagsContext must be used within TreeFeatureFlagsContextProvider!');
    }
    return context;
};
