import { useDatePickerNavigation, } from '../useDatePickerNavigation';
import { useDataDateAttribute, } from '../useDataDateAttribute';
import * as React from 'react';
import { DataGridNavigationDirection } from '@v-uik/hooks';
import { useDateLibAdapter } from '../useDateLibAdapter';
import { verticalDirection } from './config';
/**
 * Хук для навигации в DayView.
 *
 * @param root0
 * @param root0.onChangeDisplayedDate
 * @param root0.displayedDate
 */
export const useDayViewNavigation = ({ onChangeDisplayedDate, displayedDate, }) => {
    const { generateDataDateAttribute, parseDataDateAttribute } = useDataDateAttribute('keyboardDate');
    const adapter = useDateLibAdapter();
    const handleDayViewNavigation = React.useCallback((dir, date) => {
        let newDate = adapter.addDays(date, dir === DataGridNavigationDirection.right ? 1 : -1);
        if (verticalDirection.includes(dir)) {
            newDate = adapter.addDays(date, dir === DataGridNavigationDirection.bottom ? 7 : -7);
        }
        return newDate;
    }, [adapter]);
    const isSameDatePeriod = React.useCallback((newDate, date) => adapter.isSameMonth(newDate, date), [adapter]);
    const { onKeyDown, buttonOnFocus } = useDatePickerNavigation({
        generateDataDateAttribute,
        parseDataDateAttribute,
        displayedDate,
        onChangeDisplayedDate,
        onNavigate: handleDayViewNavigation,
        isSameDatePeriod,
    });
    return { onKeyDown, buttonOnFocus, generateDataDateAttribute };
};
