import { useDataDateAttribute, } from '../useDataDateAttribute';
import { useDateLibAdapter } from '../useDateLibAdapter';
import * as React from 'react';
import { DataGridNavigationDirection } from '@v-uik/hooks';
import { verticalDirection } from './config';
import { useDatePickerNavigation, } from '../useDatePickerNavigation';
import { getButtonCountInRow } from '../../utils/getButtonCountInRow';
/**
 * Хук для навигации Monthview.
 *
 * @param root0
 * @param root0.displayedDate
 */
export const useMonthViewNavigation = ({ displayedDate, }) => {
    const adapter = useDateLibAdapter();
    const [containerNode, setContainerNode] = React.useState(null);
    const handleYearViewNavigation = React.useCallback((dir, date) => {
        let newDate = adapter.addMonths(date, dir === DataGridNavigationDirection.right ? 1 : -1);
        if (verticalDirection.includes(dir)) {
            // количество в строке кнопок меняется от ширины экрана
            const countInRow = getButtonCountInRow(containerNode, document.activeElement);
            newDate = adapter.addMonths(date, dir === DataGridNavigationDirection.bottom
                ? countInRow
                : -1 * countInRow);
        }
        return newDate;
    }, [adapter, containerNode]);
    /**
     * Месяца находятся в одном "временном периоде", поэтому всегда true.
     */
    const isSameDatePeriod = React.useCallback(() => true, []);
    const { generateDataDateAttribute, parseDataDateAttribute } = useDataDateAttribute('month');
    const { buttonOnFocus, onKeyDown } = useDatePickerNavigation({
        displayedDate,
        onNavigate: handleYearViewNavigation,
        generateDataDateAttribute,
        parseDataDateAttribute,
        isSameDatePeriod,
    });
    return {
        buttonOnFocus,
        onKeyDown,
        generateDataDateAttribute,
        setContainerNode,
    };
};
