'use client';
import * as React from 'react';
import { customDateLibAdapter } from './utils/customDateLibAdapter';
export const DateLibAdapterContext = React.createContext(null);
/**
 * Компонент Provider, который позволяет дочерним компонентам, использовать
 * контекст DateLibAdapterContext.
 */
export function DateLibAdapterProvider(props) {
    const { children, dateAdapter, options } = props;
    const adapterContext = React.useMemo(() => {
        const Adapter = customDateLibAdapter(dateAdapter);
        return new Adapter(options);
    }, [dateAdapter, options]);
    return (React.createElement(DateLibAdapterContext.Provider, { value: adapterContext }, children));
}
