import * as React from 'react';
import { useDateLibAdapter } from './useDateLibAdapter';
import { DatePickerView } from '../constants/common';
import { getView } from '../utils/getView';
import { isWrongDirection } from '../utils/date';
export const useRangeViews = ({ existedViews, range, activeInputIndex, changeDate, changeOpen, setCurrentViewDate, defaultView, }) => {
    const adapter = useDateLibAdapter();
    const [currentView, setCurrentView] = React.useState(defaultView || getView(existedViews));
    const onClickMonth = () => {
        if (currentView !== DatePickerView.month) {
            setCurrentView(DatePickerView.month);
        }
    };
    const onClickChevron = (event, value) => {
        if (existedViews.day) {
            setCurrentViewDate((prevCurrentViewDate) => adapter.addMonths(prevCurrentViewDate, value));
            setCurrentView(DatePickerView.day);
        }
    };
    const onClickYear = () => {
        if (currentView !== DatePickerView.year) {
            setCurrentView(DatePickerView.year);
        }
    };
    const panelHeaderProps = {
        showMonth: existedViews.day,
        monthSelected: currentView === DatePickerView.month,
        showYear: !(existedViews.month && !existedViews.day && !existedViews.year),
        yearSelected: currentView === DatePickerView.year,
        onClickMonth,
        onClickChevron,
        onClickYear,
    };
    const onSelectDate = (newDate) => {
        if (typeof activeInputIndex === 'undefined') {
            return;
        }
        const nextRange = [...range];
        nextRange[activeInputIndex] = newDate;
        if (isWrongDirection(nextRange, activeInputIndex, adapter)) {
            changeDate(newDate, 0, [newDate, null]);
            return;
        }
        changeDate(newDate, activeInputIndex);
        if (activeInputIndex === 1 && range[0]) {
            changeOpen(false);
        }
    };
    const onSelectMonth = (newDate) => {
        if (existedViews.day) {
            setCurrentViewDate(newDate);
            setCurrentView(DatePickerView.day);
        }
        else if (typeof activeInputIndex !== 'undefined') {
            changeDate(newDate, activeInputIndex);
            if (activeInputIndex === 1 && range[0]) {
                changeOpen(false);
            }
        }
    };
    const onSelectYear = (newDate) => {
        if (existedViews.day || existedViews.month) {
            setCurrentViewDate((prevDate) => adapter.setYear(prevDate, adapter.getYear(newDate)));
            setCurrentView(DatePickerView.month);
        }
        else if (typeof activeInputIndex !== 'undefined') {
            changeDate(newDate, activeInputIndex);
            if (activeInputIndex === 1 && range[0]) {
                changeOpen(false);
            }
        }
    };
    return {
        currentView,
        setCurrentView,
        panelHeaderProps,
        onSelectDate,
        onSelectMonth,
        onSelectYear,
    };
};
