import React from 'react';
/**
 *
 */
export function getFinalChildren(originalChildren, truncatedText) {
    let currentTextIndex = 0;
    const processChildren = (child) => {
        if (typeof child === 'string') {
            const textToInsert = truncatedText.slice(currentTextIndex, currentTextIndex + child.length);
            currentTextIndex += child.length;
            return textToInsert;
        }
        else if (React.isValidElement(child) && child.props) {
            return React.cloneElement(child, Object.assign(Object.assign({}, child.props), { 
                // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
                children: React.Children.map(child.props.children, processChildren) }));
        }
        return child;
    };
    return React.Children.map(originalChildren, processChildren);
}
